$ ACR + Baseline + Qualified Pipe -> M_ACR + [$ ACR (including MBS)] + [$ ACR Baseline (Projected ACR for Future Months)] + [$ Qualified Pipeline] | REFERENCES: $ ACR (including MBS) -> M_ACR + M_ACR[$ ACR] + [$ MBS Revenue], $ ACR Baseline (Projected ACR for Future Months) -> M_ACR + 
// ACR Baseline value - totals correctly if no fiscal month is selected
 SUMX ( VALUES ( 'DimDate'[FiscalMonth] ) , [$ ACR Baseline Avg Daily (Monthly)] ), $ Qualified Pipeline -> M_ACRPipe + CALCULATE([$ Consumption Pipeline],F_AzureConsumptionPipe[SalesStageName]<>"Listen & Consult")

Expression:
// returns the count of consuming accounts. sensitive to time filtering
CALCULATE ( 
        COUNT ( DimCustomer[TPID] ), 
        FILTER ( VALUES ( DimCustomer[TPID] ), [$ ACR] > 0 )
)

// calculates the average monthly Azure Consumed Revenue per consuming (ACR > 0) account over the time period selected
DIVIDE (
    DIVIDE ( 
        [$ ACR] , 
        [INT - Number Closed Azure Months in Selection]
    ) ,
    [# Consuming Accounts]
)

